import sys

def word_pattern_brute(pattern, s):
    words = s.split()
    if len(words) != len(pattern):
        return False
    def encode(seq):
        seen, out = {}, []
        for i, x in enumerate(seq):
            if x not in seen:
                seen[x] = i
            out.append(seen[x])
        return out
    return encode(pattern) == encode(words)

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if word_pattern_brute(data[0], data[1]) else 'false')

import sys

def word_pattern_opt(pattern, s):
    words = s.split()
    if len(words) != len(pattern):
        return False
    c2w, w2c = {}, {}
    for c, w in zip(pattern, words):
        if c2w.get(c, w) != w:
            return False
        if w2c.get(w, c) != c:
            return False
        c2w[c] = w
        w2c[w] = c
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if word_pattern_opt(data[0], data[1]) else 'false')

import sys

def first_index(seq):
    seen, out = {}, []
    for x in seq:
        if x not in seen:
            seen[x] = len(out)
        out.append(seen[x])
    return out

def word_pattern_best(pattern, s):
    words = s.split()
    if len(words) != len(pattern):
        return False
    return first_index(pattern) == first_index(words)

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if word_pattern_best(data[0], data[1]) else 'false')
